import type { ReactElement } from 'react';
import { Carousel, CarouselSlide, Card } from '@design-schema/react';

function slides(names: string[]): ReactElement[] {
  return names.map((name) => (
    <CarouselSlide key={name} label={name}>
      <Card heading={name}>{name}</Card>
    </CarouselSlide>
  ));
}

<Carousel label="Featured products">{slides(['Product 1', 'Product 2', 'Product 3', 'Product 4'])}</Carousel>

